rego_policy:
package terraform.policy

import rego.v1

default allow = false

msk_cluster_created(resources) if {
    some resource in resources
    resource.type == "aws_msk_cluster"
    resource.change.actions[_] == "create"
}

broker_node_count_valid(resources) if {
    some resource in resources
    resource.type == "aws_msk_cluster"
    resource.change.after.number_of_broker_nodes == 3
}

prometheus_exporters_enabled(resources) if {
    some resource in resources
    resource.type == "aws_msk_cluster"
    resource.change.after.open_monitoring[0].prometheus[0].jmx_exporter[0].enabled_in_broker == true
    resource.change.after.open_monitoring[0].prometheus[0].node_exporter[0].enabled_in_broker == true
}

msk_connect_plugin_created(resources) if {
    some resource in resources
    resource.type == "aws_mskconnect_custom_plugin"
    resource.change.actions[_] == "create"
}

plugin_content_type_valid(resources) if {
    some resource in resources
    resource.type == "aws_mskconnect_custom_plugin"
    resource.change.after.content_type == "ZIP"
}

msk_connect_connector_created(resources) if {
    some resource in resources
    resource.type == "aws_mskconnect_connector"
    resource.change.actions[_] == "create"
}

allow if {
    msk_cluster_created(input.resource_changes)
    broker_node_count_valid(input.resource_changes)
    prometheus_exporters_enabled(input.resource_changes)
    msk_connect_plugin_created(input.resource_changes)
    plugin_content_type_valid(input.resource_changes)
    msk_connect_connector_created(input.resource_changes)
}

main if {
    allow
}

