rego_policy:
package terraform.policy

import rego.v1

default is_configuration_valid = false

is_valid_db_instance if {
    resource := input.resource_changes[_]
    resource.type == "aws_db_instance"
    has_required_db_arguments
}

has_required_db_arguments if {
    resource := input.resource_changes[_]
    resource.type == "aws_db_instance"
    after := resource.change.after
    after.allocated_storage != null
    after.engine != null
    after.username != null
    is_valid_engine(after.engine)
    is_valid_instance_class(after.instance_class)
}

is_valid_engine(engine) if {
    engine_set := {
        "mysql",
        "postgres",
        "mariadb",
        "oracle-se",
        "oracle-se1",
        "oracle-se2",
        "oracle-ee",
        "sqlserver-ee",
        "sqlserver-se",
        "sqlserver-ex",
        "sqlserver-web"
    }
    engine_set[engine]
}

is_valid_instance_class(instance_class) if {
    startswith(instance_class, "db.")
}

has_one_random_id if {
    resource := input.resource_changes[_]
    resource.type == "random_id"
}

has_one_random_password if {
    resource := input.resource_changes[_]
    resource.type == "random_password"
}

is_configuration_valid if {
    is_valid_db_instance
    has_one_random_id
    has_one_random_password
}

main if {
    is_valid_db_instance
    is_configuration_valid
}

reference_output:
terraform {
  required_version = ">= 1.15.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

provider "aws" {
  region="us-east-1"
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "random_password" "db" {
  length  = 16
  special = false
}

resource "aws_db_instance" "test" {
  identifier          = "metricbeat-test-${random_id.suffix.hex}"
  allocated_storage   = 20 // Gigabytes
  engine              = "mysql"
  instance_class      = "db.t2.micro"
  db_name                = "metricbeattest"
  username            = "foo"
  password            = random_password.db.result
  skip_final_snapshot = true // Required for cleanup
}

