rego_policy:
package terraform.policy

import rego.v1

default is_valid_db_instance = false

is_valid_db_instance if {
    resource := input.resource_changes[_]
    resource.type == "aws_db_instance"
    has_required_db_arguments
}

has_required_db_arguments if {
    resource := input.resource_changes[_]
    resource.type == "aws_db_instance"
    after := resource.change.after
    requirement1(after)
    requirement2(after)
    requirement3(after)
}

requirement1(after) if {
    after.allocated_storage != null
    after.engine != null
    after.username != null
    is_valid_engine(after.engine)
}

requirement1(after) if {
    after.snapshot_identifier != null
}

requirement1(after) if {
    after.replicate_source_db != null
}

requirement2(after) if {
    after.instance_class != null
    is_valid_instance_class(after.instance_class)
}

requirement3(after) if {
    after.password != null
}

requirement3(after) if {
    after.manage_master_user_password == true
}

requirement3(after) if {
    after.snapshot_identifier != null
}

requirement3(after) if {
    after.replicate_source_db != null
}

is_valid_engine(engine) if {
    engine_set := {
        "mysql",
        "postgres",
        "mariadb",
        "oracle-se",
        "oracle-se1",
        "oracle-se2",
        "oracle-ee",
        "sqlserver-ee",
        "sqlserver-se",
        "sqlserver-ex",
        "sqlserver-web"
    }
    engine_set[engine]
}

is_valid_instance_class(instance_class) if {
    startswith(instance_class, "db.")
}

main if {
    is_valid_db_instance
}

reference_output:
terraform {
  required_version = ">= 1.15.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

